public void setTelephone(String telephone) {
    this.telephone = telephone;
}

/**
 * The stored E.164 {@code telephone} formatted for humans: the {@code '+'} and country code, a
 * single space, then the national digits grouped in threes separated by spaces (e.g.
 * {@code '+61 412 345 678'} for the stored {@code '+61412345678'}). The raw {@code telephone}
 * stays in E.164 form. The country code is the longest leading digit run matching a known calling
 * code ({@code '+61'}, {@code '+1'}); for any other code a single leading digit is treated as the
 * country code. {@code null} when the owner has no telephone, and the value is returned unchanged
 * when it is not a {@code '+'}-prefixed E.164 string.
 */
@Transient
public String getTelephoneDisplay() {
    if (this.telephone == null) {
        return null;
    }
    if (!this.telephone.startsWith("+")) {
        return this.telephone;
    }
    String digits = this.telephone.substring(1);
    if (digits.isEmpty()) {
        return this.telephone;
    }
    String countryCode = null;
    for (String code : KNOWN_CALLING_CODES) {
        if (digits.startsWith(code) && (countryCode == null || code.length() > countryCode.length())) {
            countryCode = code;
        }
    }
    if (countryCode == null) {
        countryCode = digits.substring(0, 1);
    }
    String national = digits.substring(countryCode.length());
    StringBuilder sb = new StringBuilder("+").append(countryCode);
    for (int i = 0; i < national.length(); i++) {
        if (i % 3 == 0) {
            sb.append(' ');
        }
        sb.append(national.charAt(i));
    }
    return sb.toString();
}

